// Locale helpers for read-only multi-language checks.
// Locale ONLY via URL prefix (/en, /ru, /ar) — never the header language switcher (it saves the user's setting).
import { Page } from '@playwright/test';

export type Lang = 'he' | 'en' | 'ru' | 'ar';
export const LANGS: Lang[] = ['he', 'en', 'ru', 'ar'];

/** '/collaborations/x?y=1' → '/en/collaborations/x?y=1' (he = no prefix). Strips an existing locale prefix first. */
export function withLocale(pathAndQuery: string, lang: Lang): string {
  const clean = pathAndQuery.replace(/^\/(he|en|ru|ar)(?=\/|$|\?)/, '') || '/';
  return lang === 'he' ? clean : `/${lang}${clean.startsWith('/') ? clean : `/${clean}`}`;
}

/** Current page path + query, without the locale prefix. */
export function currentPath(page: Page): string {
  const u = new URL(page.url());
  return (u.pathname.replace(/^\/(he|en|ru|ar)(?=\/|$)/, '') || '/') + u.search;
}

/** Removes bidi control marks and collapses whitespace — for comparing innerText of RTL/LTR mixed strings. */
export function norm(s: string): string {
  return s.replace(/[‎‏‪-‮⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
}

/** dd.mm.yyyy in Israel time. */
export function ilDate(d: Date): string {
  const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', day: '2-digit', month: '2-digit', year: 'numeric' }).formatToParts(d);
  const get = (t: string) => p.find((x) => x.type === t)!.value;
  return `${get('day')}.${get('month')}.${get('year')}`;
}

/** yyyy-mm-dd in Israel time (value of <input type="date">). */
export function ilIsoDate(d: Date): string {
  const [dd, mm, yyyy] = ilDate(d).split('.');
  return `${yyyy}-${mm}-${dd}`;
}
